import {defaults,parseCandles,research,demoCandles,clock} from './engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function saved(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
let cfg={...defaults,...saved('gaplab-config',{})},notes=saved('gaplab-notes',[]),bars=demoCandles(),source='Synthetic demonstration',result=null,selected=0,lastError='',view='price';
const names={overview:'Research desk',blueprint:'Strategy blueprint',backtest:'Backtest lab',recognition:'A++ recognition',journal:'Research journal',connection:'TopstepX roadmap'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Browser storage is unavailable. Export your research to keep a copy.')}}
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(x);
const num=x=>Number(x).toFixed(2),date=t=>`${clock(t).day} ${clock(t).hm} ET`;
function heading(eyebrow,title,desc,buttons=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${buttons}</div></div>`}
const importButton='<button class="button" data-action="import">↑ Import candles</button>';
const runButton='<button class="button primary" data-action="run">↗ Run backtest</button>';
const badge=()=>`<span class="tag ${source.startsWith('Synthetic')?'amber':''}">${source.startsWith('Synthetic')?'SYNTHETIC DATA':'IMPORTED CANDLES'}</span>`;
function chart(hero=false){let bs=(hero?demoCandles().slice(210,268):bars.slice(-100));if(!bs.length)return '';const w=700,h=hero?245:250,pad=22,max=Math.max(...bs.map(b=>b.h)),min=Math.min(...bs.map(b=>b.l)),span=max-min||1,y=v=>pad+(max-v)/span*(h-pad*2),dx=(w-70)/bs.length;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${hero?'Illustrative':'Dataset'} candlestick chart"><defs><pattern id="grid${hero}" width="70" height="48" patternUnits="userSpaceOnUse"><path d="M 70 0 L 0 0 0 48" fill="none" stroke="#dce3d3" stroke-width=".7"/></pattern></defs><rect width="${w}" height="${h}" fill="url(#grid${hero})"/>`;
if(hero){svg+=`<rect x="180" y="52" width="345" height="37" fill="#c8d4b3" opacity=".6" stroke="#9cae85" stroke-dasharray="4 4"/><text x="190" y="69" fill="#82936c" font-size="9">FAIR VALUE GAP</text><line x1="80" x2="650" y1="201" y2="201" stroke="#9bb17b" stroke-dasharray="5 4"/><text x="500" y="216" font-size="9" fill="#7e9463">LIQUIDITY TARGET</text>`;}
bs.forEach((b,i)=>{let x=12+i*dx,color=b.c>=b.o?'#b8c7a3':'#3a5e42';svg+=`<line x1="${x}" x2="${x}" y1="${y(b.h)}" y2="${y(b.l)}" stroke="${color}" stroke-width="1"/><rect x="${x-dx*.28}" width="${Math.max(1,dx*.56)}" y="${y(Math.max(b.o,b.c))}" height="${Math.max(1,Math.abs(y(b.o)-y(b.c)))}" fill="${color}"/>`;});if(!hero){for(let k=0;k<5;k++){let v=max-(max-min)*k/4;svg+=`<text x="${w-44}" y="${y(v)+3}" fill="#9ba68e" font-size="8">${v.toFixed(0)}</text>`;}}
return svg+'</svg>';}
function equityChart(){if(!result?.trades.length)return '<div class="empty">Run a backtest to calculate the equity curve.</div>';let e=0,values=[0,...result.trades.map(t=>(e+=t.pnl))],lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1,points=values.map((v,i)=>`${25+i*620/(values.length-1)},${210-(v-lo)/span*180}`).join(' ');return `<svg viewBox="0 0 700 250" role="img" aria-label="Closed-trade cumulative net profit"><path d="M25 30H660M25 90H660M25 150H660M25 210H660" stroke="#e7ebdf" fill="none"/><polyline points="${points}" fill="none" stroke="#416644" stroke-width="2"/><text x="25" y="240" font-size="9" fill="#8f9e82">Trade 0</text><text x="590" y="240" font-size="9" fill="#8f9e82">Trade ${result.trades.length}</text></svg>`}
function metrics(){const r=result;return `<div class="metrics">${[['Net result',r?money(r.net):'—','After configured costs','↗'],['Win rate',r?r.winRate.toFixed(1)+'%':'—',r?`${r.trades.length} simulated trades`:'Awaiting a backtest','◎'],['Profit factor',r?(r.profitFactor===null?'—':r.profitFactor.toFixed(2)):'—','— when no losing trades','⌁'],['Max. drawdown',r?money(r.maxDrawdown):'—','Closed-trade equity only','↘']].map(([label,val,sub,icon])=>`<div class="metric"><div class="metric-top">${label}<span>${icon}</span></div><div class="metric-value ${label==='Net result'&&r?(r.net>=0?'positive':'negative'):''}">${val}</div><div class="metric-sub">${sub}</div></div>`).join('')}</div>`}
function tradeTable(limit=100){if(!result)return '<div class="empty">Your results will appear here after you run a backtest.</div>';if(!result.trades.length)return '<div class="empty">No trades qualified under these rules. Review the candidate checklist or adjust your research assumptions.</div>';return `<div class="table-wrap"><table><thead><tr><th>Entry / New York</th><th>Model</th><th>Entry</th><th>Stop</th><th>Target</th><th>Qty</th><th>Net P&L</th><th>Exit</th></tr></thead><tbody>${result.trades.slice(-limit).reverse().map(t=>`<tr><td>${date(t.entryTime)}</td><td>${t.setup==='A'?'5m inversion':'1m continuation'}</td><td>${num(t.entry)}</td><td>${num(t.stop)}</td><td>${num(t.target)}</td><td>${t.qty}</td><td class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td><td>${t.reason}</td></tr>`).join('')}</tbody></table></div>`}
function overview(){return heading('OBSERVE. DEFINE. VALIDATE.','Find the setup. Prove the edge.','A personal research lab for your MNQ fair value gap strategy.',importButton+'<a class="button primary" href="#blueprint">Open blueprint ↗</a>')+`<section class="hero"><div class="hero-copy"><div class="eyebrow" style="margin-bottom:14px">FROM TRADE RECAP TO REPEATABLE RULES</div><h2>Good trades start with<br>a clear blueprint.</h2><p>Turn the ideas from your videos into testable rules. Study the context, inspect each trigger, and build evidence for an A++ setup.</p><a class="button lime" href="#recognition">Explore A++ recognition <span>↗</span></a></div><div class="hero-visual"><div class="hero-label">MNQ / STRATEGY ILLUSTRATION</div>${chart(true)}<span class="hero-tag">Context → confirmation → candidate</span></div></section><div class="section-header"><h2>Research at a glance</h2>${badge()}</div>${metrics()}<div class="grid-main"><section class="panel"><div class="panel-heading"><div><h2>Market study</h2><p>${esc(source)} · ${bars.length.toLocaleString()} one-minute candles</p></div><div class="tabs-inline"><button data-action="price" class="${view==='price'?'active':''}">Price</button><button data-action="equity" class="${view==='equity'?'active':''}">Equity</button></div></div><div class="chart">${view==='price'?chart():equityChart()}</div><div class="chart-caption"><span>${view==='price'?'Last 100 candles · one-minute bars':'Cumulative net result · trade exits'}</span><span>${view==='price'?'NO LIVE FEED':'SIMULATED RESULTS'}</span></div><div class="legend"><span>${view==='price'?'Bearish candles':'Net equity'}</span><span>${view==='price'?'Bullish candles':'After costs'}</span></div></section><section class="panel"><div class="panel-heading"><h2>Your strategy models</h2><span class="tag gray">v0.1 / RESEARCH</span></div><div class="setup-row"><div class="setup-num">01</div><div><h3>Five-minute inversion</h3><p>Higher-timeframe context. A five-minute close below a bullish gap. Liquidity below.</p><a href="#blueprint" class="link-button">Study the A+ model ↗</a></div></div><div class="setup-row"><div class="setup-num">02</div><div><h3>One-minute continuation</h3><p>Bearish displacement, a gap retest, and a lower liquidity objective.</p><a href="#blueprint" class="link-button">Study the continuation model ↗</a></div></div><div class="notice"><strong>A++ is a research hypothesis.</strong> It adds explicit context, target, and risk filters to the A+ example. It is not a demonstrated success rate.</div></section></div><section class="panel"><div class="panel-heading"><div><h2>Latest simulated trades</h2><p>Calculated from the currently selected dataset and rules.</p></div><a class="button small" href="#backtest">Open backtest lab ↗</a></div>${tradeTable(5)}</section>`}
function blueprint(){return heading('THE WORKING THESIS','The strategy, made explicit.','Separate what the videos establish from the assumptions we still need to test.','<a class="button primary" href="#backtest">Test the blueprint ↗</a>')+`<div class="two-cols"><section class="panel"><div class="panel-heading"><h2>01 / A+ inversion model</h2><span class="tag">VIDEO-DERIVED</span></div>${[['Context','Price retraces into a 15-minute bearish fair value gap. The narrator checks smaller timeframes for bearish confirmation.','00:08–00:43'],['Wait for confirmation','Do not enter merely because one-, two-, or three-minute gaps have inverted. Wait for the five-minute candle to close below the five-minute bullish gap.','01:11–01:39'],['Short toward liquidity','The stated objectives are marked one-hour/four-hour liquidity and the previous day’s lunch low.','01:39–01:51']].map(([h,p,t],i)=>`<div class="step"><span class="step-index">0${i+1}</span><div><h3>${h}</h3><p>${p}</p><span class="tag gray">LONGER CLIP · ${t}</span></div></div>`).join('')}</section><section class="panel"><div class="panel-heading"><h2>02 / Continuation model</h2><span class="tag">VIDEO-DERIVED</span></div>${[['Identify the draw','Mark the Asia/hourly low and other lower liquidity levels before evaluating a short.','00:21–00:32'],['Look for displacement','A strong bearish move leaves a one-minute fair value gap. The trader sells the return into that gap.','00:32–00:49'],['Treat it as a separate model','He rates this trade below A+. His account deadline affected the decision; the research engine does not reproduce that pressure or sizing.','00:50–01:04']].map(([h,p,t],i)=>`<div class="step"><span class="step-index">0${i+1}</span><div><h3>${h}</h3><p>${p}</p><span class="tag gray">SHORTER CLIP · ${t}</span></div></div>`).join('')}</section></div><section class="panel"><div class="panel-heading"><div><h2>Defining an A++ candidate</h2><p>A proposed research filter, not a category established in the clips.</p></div><span class="tag amber">HYPOTHESIS</span></div><div class="formula">15m bearish gap context + 5m bullish gap inversion + a supplied liquidity target + sufficient reward / risk + risk limits satisfied = <strong>A++ research candidate</strong></div><div class="three-cols" style="margin-top:22px"><div><h3>Known from the clips</h3><p>Short-side examples, gap retests, completed five-minute confirmation, and objectives at marked liquidity.</p></div><div><h3>Assumptions in this version</h3><p>Three-candle wick gaps; next-minute-open entry; five-bar swing-high stop; gap age limits; session window; fixed-R fallback. Each is a test parameter.</p></div><div><h3>Still unresolved</h3><p>Exact session definitions, gap selection priorities, stop logic, news filters, partial exits, breakeven rules, and long-side equivalents.</p></div></div></section><section class="panel"><h2>Recognition research roadmap</h2><div class="roadmap"><div><section><h3>Explicit rules — available now</h3><p>Detect gaps and completed-candle inversions in imported data. Inspect pass/fail reasons for each candidate.</p></section></div><div><section><h3>A labeled reference library — build next</h3><p>Save winning, losing, rejected, and ambiguous examples. Label only information that was available at the decision time. Keep future outcomes separate.</p></section></div><div><section><h3>AI-assisted recognition — not trained yet</h3><p>Train or evaluate a model against your labels, then measure precision, missed setups, and results on later, unseen sessions. A model score must not be presented as a win probability without calibration.</p></section></div></div></section><div class="source-line">Sources: your two uploaded July 15 recap clips. Automated transcription was checked against sampled chart frames; ambiguous descriptions remain assumptions.</div>`}
function field(label,key,type='number',step='any'){return `<label>${label}<input name="${key}" type="${type}" step="${step}" value="${esc(cfg[key])}" ${type==='number'?'min="0"':''}></label>`}
function backtest(){return heading('EVIDENCE BEFORE EXECUTION','Backtest lab','Import one-minute MNQ candles. Change a hypothesis. Measure the result.',importButton+runButton)+`<div class="notice" style="margin:0 0 20px"><strong>${esc(source)}.</strong> ${source.startsWith('Synthetic')?'Demo prices are generated, not real market history. These results cannot establish an edge.':'Imported candles have not been independently verified. Use one unadjusted MNQ contract per file.'} Settings and notes stay in this browser; imported candles stay in memory until you leave or reload.</div><div class="grid-main"><div><section class="panel"><div class="panel-heading"><h2>Research parameters</h2><span class="tag amber">ASSUMPTIONS / EDITABLE</span></div><form id="config"><div class="settings"><label>Strategy model<select name="setup"><option value="A" ${cfg.setup==='A'?'selected':''}>A+ / Five-minute inversion</option><option value="B" ${cfg.setup==='B'?'selected':''}>B / One-minute continuation</option></select></label>${field('Risk per trade ($)','risk')}${field('Maximum MNQ contracts','maxContracts','number','1')}${field('Daily loss budget ($)','dailyLoss')}${field('Minimum reward / risk','rr')}${field('Round-trip fee / contract ($)','commission')}${field('Slippage / side (ticks)','slipTicks','number','1')}${field('Stop buffer (points)','stopBuffer')}${field('Minimum gap (points)','minGap')}${field('B-model displacement body (points)','displacement')}${field('Entry window start · New York','sessionStart','time')}${field('Entry window end · New York','sessionEnd','time')}<label class="wide">Liquidity levels for this research file (comma-separated prices)<input name="levels" value="${esc(cfg.levels)}" placeholder="Example: 21925, 21880"></label></div><label class="check-label"><input name="requireContext" type="checkbox" ${cfg.requireContext?'checked':''}> Require 15-minute bearish gap context for A+ entries</label><label class="check-label"><input name="requireLiquidity" type="checkbox" ${cfg.requireLiquidity?'checked':''}> Require a supplied liquidity target; otherwise use fixed-R fallback</label><div class="actions"><button class="button primary" type="submit">Apply rules & run ↗</button><button class="button" type="button" data-action="reset">Reset assumptions</button></div><p id="formError" class="error">${esc(lastError)}</p></form></section><section class="panel"><div class="panel-heading"><h2>Dataset</h2>${badge()}</div><div class="dropzone"><div style="font-size:23px;color:#90a278">↑</div><h3>Bring your own market history</h3><p>CSV · one-minute bars · MNQ · maximum 200,000 rows</p><button class="button" data-action="import">Choose CSV file</button> <button class="button" data-action="demo">Load synthetic demo</button></div><p>${bars.length.toLocaleString()} candles · ${date(bars[0].t)} → ${date(bars.at(-1).t)}</p><details><summary>CSV format & data requirements</summary><pre>timestamp,open,high,low,close\n2026-01-05T14:30:00Z,22000,22003,21998,22001</pre><p>Timestamps represent candle open times. Supply a UTC offset or Z, or Unix seconds/milliseconds. Rows must be ascending, unique, minute-aligned, and contain valid positive OHLC values. Five- and fifteen-minute bars are formed only from complete, contiguous minute groups. Use actual contract prices rather than a back-adjusted continuous series.</p><button class="button small" data-action="sample">Download demo CSV</button></details></section></div><div><section class="panel"><h2>How this simulation works</h2><ul class="checklist"><li class="pass">Completed candles only</li><li class="pass">Entry at next minute’s open</li><li class="pass">One open position at a time</li><li class="pass">MNQ: $2 per point / 0.25 tick</li><li class="pass">Costs included in risk sizing</li><li class="pass">Stop checked before target</li></ul><details open><summary>Important model assumptions</summary><p>Stops use the highest high of the last five one-minute candles plus the buffer. Stops include adverse slippage; if price gaps through a stop, the simulation fills at the worse open. Target fills use the target price. Open trades close on the first available candle at/after 16:00 New York, a session boundary, or the dataset’s end.</p><p>The 15m context lasts up to 60 minutes. Five-minute bullish gaps expire after 60 minutes; one-minute bearish gaps expire after 30. A B-model retest must close bearish. No partial exits, queue simulation, news filter, or Topstep account drawdown rules are modeled.</p><p>Supplied liquidity levels apply throughout the file. Only enter levels known before the test period. For multi-day research, split files or use fixed-R targets to avoid hindsight. The nearest lower supplied level is used, then filtered by minimum R.</p></details><div class="notice">Parameters are research defaults, not recommended risk settings. A daily budget is a sizing/entry limit; slippage can exceed it.</div></section><section class="panel"><h2>Keep a clean experiment</h2><p>Choose settings on an earlier sample. Export the report. Hold those rules fixed when testing a later period. This version does not automatically split or optimize datasets.</p><button class="button" data-action="export">Export current report ↗</button></section></div></div>${metrics()}<section class="panel"><div class="panel-heading"><h2>Simulated trade log</h2><button class="button small" data-action="trades">Download trades CSV</button></div>${tradeTable()}${result?.trades.length>100?'<p>Showing the latest 100 trades. Export for the full log.</p>':''}</section>`}
function recognition(){const ss=result?.signals||[],s=ss[selected]||ss.at(-1),pass=s?s.checks.filter(x=>x.pass).length:0,total=s?.checks.length||6;return heading('EXPLAINABLE SETUP RESEARCH','What makes an A++ setup?','Inspect the evidence behind a candidate. Every rule should have a reason.','<a class="button primary" href="#backtest">Run a detection study ↗</a>')+`<div class="notice" style="margin:0 0 22px"><strong>Rule-based detector · no AI model connected.</strong> A++ is the working definition in your blueprint. The checklist measures rule matches, not the probability of a winning trade.</div><div class="grid-main"><section class="panel"><div class="panel-heading"><div><h2>Candidate review</h2><p>${ss.length} signals found in the current research run</p></div>${badge()}</div>${ss.length?`<label>Select a signal<select id="signalSelect">${ss.map((a,i)=>`<option value="${i}" ${i===selected?'selected':''}>${date(a.t)} · ${a.grade} · ${a.status}</option>`).join('')}</select></label>`:'<div class="empty">Run a backtest to detect candidates.<br>Try imported data or experiment with the synthetic demo.</div>'}<div class="recognition-head" style="margin:25px 0"><div class="score">${s?pass:'—'}<span style="font-size:20px;color:#9cad8d"> / ${total}</span></div><div><h3>${s?esc(s.grade):'Awaiting evidence'}</h3><p>Rules matched<br>${s?esc(s.status):'No candidate selected'}</p></div></div><ul class="checklist">${(s?s.checks:[{label:'Completed candle signal'},{label:'Five-minute gap inversion'},{label:'15-minute bearish gap context'},{label:'Liquidity target supplied'},{label:`Reward / risk ≥ ${cfg.rr}`},{label:'Size fits risk limits'}]).map(c=>`<li class="${s?(c.pass?'pass':'fail'):''}">${esc(c.label)}</li>`).join('')}</ul>${s?.entry?`<div class="mini-stat">Indicative entry <b>${num(s.entry)}</b></div><div class="mini-stat">Stop / target <b>${num(s.stop)} / ${num(s.target)}</b></div><div class="mini-stat">Reward / risk <b>${Number.isFinite(s.rr)?s.rr.toFixed(2):'—'}R</b></div>`:''}${s?'<button class="button" data-action="label">Add this candidate to journal ↗</button>':''}</section><div><section class="panel"><h2>The A++ blueprint</h2><div class="step"><span class="step-index">01</span><div><h3>Context first</h3><p>Price trades into a known bearish 15-minute gap, identified using only completed bars.</p></div></div><div class="step"><span class="step-index">02</span><div><h3>Five-minute confirmation</h3><p>A completed candle closes below a previously formed bullish five-minute gap.</p></div></div><div class="step"><span class="step-index">03</span><div><h3>A destination and a defined invalidation</h3><p>A pre-supplied liquidity target offers enough reward relative to the explicit stop. Position size fits the configured budget.</p></div></div><div class="notice">A++ recognition currently applies only to the five-minute model. The one-minute continuation setup stays a separate research candidate.</div></section><section class="panel"><h2>From checklist to AI</h2><p>Build a balanced reference set: qualified setups, failed setups, and ordinary market conditions. Record your human label before reviewing the outcome.</p><p>Future AI work should be evaluated on unseen sessions and compared with this transparent rule baseline. No training, image recognition, or predictive confidence is implemented in this version.</p><a class="link-button" href="#journal">Start the reference library ↗</a></section></div></div>`}
function journal(){return heading('YOUR REFERENCE LIBRARY','Keep the evidence.','Record observations, challenge the rules, and label candidates for future model research.','<button class="button" data-action="export">Export research ↗</button>')+`<div class="two-cols"><section class="panel"><h2>Add a research note</h2><form id="noteForm"><label style="margin-top:20px">Title<input name="title" required maxlength="160" placeholder="e.g. Five-minute inversion after a 15m gap retest"></label><label style="margin-top:15px">Human classification<select name="label"><option>A++ candidate</option><option>A+ candidate</option><option>B continuation</option><option>Rejected setup</option><option>Ambiguous / needs review</option><option>Research observation</option></select></label><label style="margin-top:15px">Observation<textarea name="body" required maxlength="12000" placeholder="What was known before entry? Which rule passed or failed? What remains subjective?"></textarea></label><button class="button primary" type="submit" style="margin-top:15px">Save research note ↗</button></form><div class="notice">Notes are stored in this browser. Export a backup to preserve them. A journal note is a research label, not a verified training dataset.</div></section><section class="panel"><div class="panel-heading"><h2>Research notes</h2><span class="tag gray">${notes.length} ENTRIES</span></div>${notes.length?notes.slice().reverse().map(n=>`<article class="journal-card"><span class="tag">${esc(n.label)}</span><h3 style="margin-top:12px">${esc(n.title)}</h3><small>${esc(new Date(n.created).toLocaleString())}</small><p>${esc(n.body)}</p><button class="link-button" data-delete="${esc(n.id)}">Delete note</button></article>`).join(''):'<div class="empty">Your next insight belongs here.<br>Add an observation or save a detected candidate.</div>'}</section></div>`}
function connection(){return heading('TOPSTEPX / PERSONAL DEVICE','A blueprint for execution.','Research here. Validate locally. Keep order flow on your Mac.','<a class="button" target="_blank" rel="noopener" href="https://help.topstep.com/en/articles/11187768-topstepx-api-access">Official API guide ↗</a>')+`<section class="panel"><div class="panel-heading"><h2>Your current plan</h2><span class="tag amber">NOT CONNECTED</span></div><div class="three-cols"><div><div class="eyebrow">PLATFORM</div><h2 style="margin-top:12px">TopstepX</h2><p>Express Funded · Mac<br>API subscription/linking not yet confirmed.</p></div><div><div class="eyebrow">THIS WEBSITE</div><h2 style="margin-top:12px">Research & recognition</h2><p>Strategy documentation, CSV research, transparent detection, simulation, and journal.</p></div><div><div class="eyebrow">LATER PHASE</div><h2 style="margin-top:12px">Local execution agent</h2><p>Not implemented or connected. No credentials are requested or stored by this website.</p></div></div><div class="notice"><strong>Hosting boundary:</strong> Topstep requires order activity to originate on your personal device. Its guidance permits remote research and analytics but prohibits remote order placement, modification, cancellation, and automated triggers that reach order endpoints. This site has no order-routing or trigger connection.</div></section><div class="two-cols"><section class="panel"><h2>Implementation stages</h2><div class="roadmap"><div><section><h3>Write and test the research specification</h3><p>Resolve stops, level definitions, session rules, and what A++ means. Compare the rules against additional videos and losing examples.</p></section></div><div><section><h3>Validate on historical market data</h3><p>Use clean MNQ contract history, realistic fees, and a held-out period. Measure net results, drawdown, and false-positive setups.</p></section></div><div><section><h3>Build a standalone Mac agent</h3><p>Run market-data ingestion, signal detection, risk checks, and any future order transmission locally. Store credentials locally. Add duplicate-order protection, reconciliation, stale-data checks, and a kill switch.</p></section></div><div><section><h3>Test in a TopstepX Practice account</h3><p>Topstep says no separate API sandbox is available. Verify behavior in Practice before considering an eligible Express Funded account.</p></section></div></div></section><section class="panel"><h2>Before connecting an account</h2><ul class="checklist"><li>Confirm ProjectX API access and linking</li><li>Confirm the exact eligible account</li><li>Approve the final strategy specification</li><li>Set per-trade and daily risk limits</li><li>Map Topstep account drawdown rules</li><li>Verify practice fills and recovery behavior</li></ul><p>These are implementation requirements for the future execution phase. The current site is usable without an API subscription.</p><div class="source-line">Sources: <a target="_blank" rel="noopener" href="https://help.topstep.com/en/articles/11187768-topstepx-api-access">TopstepX API Access</a> · <a target="_blank" rel="noopener" href="https://gateway.docs.projectx.com/docs/getting-started/">ProjectX API documentation</a></div></section></div>`}
function render(){let page=location.hash.slice(1)||'overview';if(!names[page])page='overview';$('#breadcrumb').textContent=names[page];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#main').innerHTML=({overview,blueprint,backtest,recognition,journal,connection}[page])();bind();}
function run(){try{result=research(bars,cfg);selected=Math.max(0,result.signals.length-1);lastError='';render();toast(`${result.trades.length} simulated trades · ${result.signals.length} detected candidates`)}catch(e){lastError=e.message;render();toast(e.message)}}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function exportReport(){download('gaplab-research.json',JSON.stringify({version:'0.1',exported:new Date().toISOString(),source,instrument:'MNQ',dataRange:{start:bars[0].t,end:bars.at(-1).t,bars:bars.length},strategyStatus:'Working hypothesis, not validated or AI-trained',config:cfg,results:result,notes},null,2));toast('Research report exported')}
function csvOut(bs){return 'timestamp,open,high,low,close\n'+bs.map(b=>[new Date(b.t).toISOString(),b.o,b.h,b.l,b.c].join(',')).join('\n')}
function action(a){if(a==='import')$('#csvFile').click();if(a==='run'){if($('#config'))$('#config').requestSubmit();else run();}if(a==='export')exportReport();if(a==='price'||a==='equity'){view=a;render()}if(a==='demo'){bars=demoCandles();source='Synthetic demonstration';result=null;render();toast('Synthetic demo loaded; previous results cleared')}if(a==='sample')download('gaplab-synthetic-demo.csv',csvOut(demoCandles()),'text/csv');if(a==='reset'){cfg={...defaults};persist('gaplab-config',cfg);result=null;render();toast('Research defaults restored')}if(a==='trades'){if(!result?.trades.length){toast('Run a backtest with qualifying trades first');return}const keys=['entryTime','exitTime','setup','grade','entry','stop','target','qty','gross','pnl','reason'];download('gaplab-simulated-trades.csv',keys.join(',')+'\n'+result.trades.map(t=>keys.map(k=>JSON.stringify(k.endsWith('Time')?new Date(t[k]).toISOString():t[k])).join(',')).join('\n'),'text/csv')}if(a==='label'){const s=result.signals[selected];notes.push({id:crypto.randomUUID(),created:new Date().toISOString(),label:s.grade,title:`MNQ ${s.setup==='A'?'5m inversion':'1m continuation'} · ${date(s.t)}`,body:`Source: ${source}\nStatus: ${s.status}\n${s.checks.map(c=>`${c.pass?'PASS':'FAIL'}: ${c.label}`).join('\n')}\nResearch hypothesis; human review needed.`,signal:s});persist('gaplab-notes',notes);location.hash='journal';toast('Candidate saved for human review')}}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$('#signalSelect')?.addEventListener('change',e=>{selected=+e.target.value;render()});$('#config')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),next={...cfg};for(const [k,v] of Object.entries(defaults)){if(typeof v==='boolean')next[k]=f.has(k);else if(typeof v==='number')next[k]=+f.get(k);else next[k]=f.get(k);}try{research(bars.slice(0,20),next);cfg=next;persist('gaplab-config',cfg);run()}catch(err){$('#formError').textContent=err.message;toast(err.message)}});$('#noteForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);notes.push({id:crypto.randomUUID(),created:new Date().toISOString(),title:f.get('title'),label:f.get('label'),body:f.get('body')});persist('gaplab-notes',notes);render();toast('Research note saved')});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{notes=notes.filter(n=>n.id!==b.dataset.delete);persist('gaplab-notes',notes);render();toast('Note deleted')})}
$('#csvFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('Please use a CSV under 30 MB.');const imported=parseCandles(await file.text());bars=imported;source=file.name;result=null;selected=0;render();toast(`Imported ${bars.length.toLocaleString()} candles. Run a backtest to inspect candidates.`)}catch(err){toast(err.message)}finally{e.target.value=''}});$('#exportTop').onclick=exportReport;window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
